"""Text templates embedded from the full Tobias Holzmann case."""

FILES = {
    '.color': "#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  10 Februar 2025                 #\n#----------------------------------------------#\n# Location:    www.Holzmann-cfd.de             #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n#----------------------------------------------#\n\n\n# Color definition for some bash highlight manipulation\n#------------------------------------------------------------------------------\nRED='\\e[0;31m'\nGREEN='\\e[0;32m'\nNC='\\e[0m'\nORANGE='\\033[0;33m'\nGRAY='\\e[0;37m'\nFL='\\033[0;36m'\n\n\n#------------------------------------------------------------------------------\n",
    '.preamble': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  10 Februar 2025                 #\n#----------------------------------------------#\n# Location:    https://Holzmann-cfd.com        #\n# Email:       community@Holzmann-cfd.com      #\n#----------------------------------------------#\n\n\n#------------------------------------------------------------------------------\n# Preamble with the information about the tutorial\necho -en "\n-------------------------------------------------------------------------------\n${GRAY}Tutorial by Tobias Holzmann${NC} :: Generated during September 2016\n${GRAY}Build for OpenFOAM version${NC}  :: OpenFOAM-12\n${GRAY}Tested on system${NC}            :: Ubuntu 24.04.1\n${GRAY}The case was updated on${NC}     :: 10 Februar 2025\n-------------------------------------------------------------------------------\n\n\n${GREEN}Topic: Generate a AMI mesh using snappyHexMesh${NC}\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\n# Check the OpenFOAM version\necho -e "   - Check OpenFOAM version. We need $foamVersion"\nuserFoamVersion=`echo "$WM_PROJECT-$WM_PROJECT_VERSION"` \n\nif [ "$userFoamVersion" == "$foamVersion" ]\nthen\n    echo -e  "   - ${GREEN}$foamVersion found...${NC}"\n\nelse\n    echo -e  "   - ${ORANGE}You are not using the correct OpenFOAM version"\n    echo -en "     Your version is $userFoamVersion and we need ${GREEN}"\n    echo -e  "$foamVersion${NC}\\n"\n\n    while true\n    do\n        echo -en  "   - Proceed with your OpenFOAM version (y/n): "\n        read proceed\n\n        if [ "$proceed" == "y" ]\n        then\n            break\n\n        elif [ "$proceed" == "n" ]\n        then\n            echo -e "\\n\\n"\n            exit\n\n        fi\n    done\nfi\n\n\n#------------------------------------------------------------------------------\n',
    '0.orig/U': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volVectorField;\n    location    "0";\n    object      U;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 1 -1 0 0 0 0];\n\ninternalField   uniform (0 0 0);\n\nboundaryField\n{\n    #includeEtc         "caseDicts/setConstraintTypes"\n\n    inlet1\n    {\n        type            fixedValue;\n        value           uniform (0 0 0.08);\n    }\n\n    inlet2\n    {\n        type            fixedValue;\n        value           uniform (0 0 0.65);\n    }\n\n    outlet\n    {\n        type            inletOutlet;\n        inletValue      uniform (0 0 0);\n        value           uniform (0 0 0);\n    }\n\n    movingWalls \n    {\n        type            movingWallVelocity;\n        value           uniform (0 0 0);\n    }\n\n    staticWalls\n    {\n        type            noSlip;\n    }\n\n    AMI1\n    {\n        type            zeroGradient;\n    }\n    AMI2\n    {\n        type            zeroGradient;\n    }\n}\n\n\n// ************************************************************************* //\n',
    '0.orig/p': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volScalarField;\n    location    "0";\n    object      p;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 2 -2 0 0 0 0];\n\ninternalField   uniform 0;\n\nboundaryField\n{\n    #includeEtc         "caseDicts/setConstraintTypes"\n\n    inlet1\n    {\n        type            zeroGradient;\n    }\n\n    inlet2\n    {\n        type            zeroGradient;\n    }\n\n    outlet\n    {\n        type            fixedValue;\n        value           uniform 0;\n    }\n\n    movingWalls \n    {\n        type            zeroGradient;\n    }\n\n    staticWalls \n    {\n        type            zeroGradient;\n    }\n\n    AMI1\n    {\n        type            zeroGradient;\n    }\n\n    AMI2\n    {\n        type            zeroGradient;\n    }\n}\n\n\n// ************************************************************************* //\n',
    'clean': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Last Change: November 2015                   #\n# Topic:                                       #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n#----------------------------------------------#\n\n\n#-------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\n\n\n#-------------------------------------------------------------------------------\nfoamCleanTutorials\nrm -rf constant/triSurface/*.eMesh constant/polyMesh\nrm -rf 0 log* constant/extend*\n\n\n#-------------------------------------------------------------------------------\n',
    'constant/dynamicMeshDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      dynamicMeshDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nmover\n{\n    type                motionSolver;\n    libs                ("libfvMotionSolvers.so");\n\n    motionSolver                solidBody;\n    solidBodyMotionFunction     rotatingMotion;\n\n    cellZone    innerAMI;\n    origin      (0 0 0);\n    axis        (0 0 1);\n    omega       2; // rad/s\n}\n\n\n// ************************************************************************* //\n',
    'constant/transportProperties': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      transportProperties;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ntransportModel  Newtonian;\n\nnu              [0 2 -1 0 0 0 0] 1e-6;\n\n// ************************************************************************* //\n',
    'constant/turbulenceProperties': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      turbulenceProperties;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsimulationType  laminar;\n\n\n// ************************************************************************* //\n',
    'run': '#!/bin/bash\n#\n#-------------------------------------------------#\n# Contributor: Tobias Holzmann                    #\n# Updated on:  10 Februar 2025                    #\n#-------------------------------------------------#\n# Topic:       Generate a AMI mesh using sHM      #\n# OpenFOAM:    version 12 (Foundation)            #\n#-------------------------------------------------#\n# Website:     https://Holzmann-cfd.com           #\n# Email:       community@Holzmann-cfd.com         #\n#-------------------------------------------------#\n\n\n#------------------------------------------------------------------------------\nfoamVersion="OpenFOAM-12"\n\n\n#------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\nsource clean\nsource .color\nsource .preamble\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\nStart meshing\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\necho -e "   - Create background mesh"\nideasUnvToFoam cad/backgroundMesh.unv >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Meshing with snappyHexMesh (approx 2 minutes)"\nsnappyHexMesh -overwrite >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Update AMI patch infos / also \'changeDict\' could be used"\ncreatePatch -overwrite >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Create nonConformal patches"\ncreateNonConformalCouples -overwrite AMI1 AMI2 >> logMeshing\n\nrm -rf 0\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\n-------------------------------------------------------------------------------\nEnd Meshing\\n\n"\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\nStart simulation\\n\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\nread -p "   - Calculate simulation (1) or just move the mesh (2): " input\n\n\n#------------------------------------------------------------------------------\necho "   - Calculate simulation"\nif [ $input -eq 1 ]\nthen\n    echo "   - Change timestep and save interval"\n    foamDictionary system/controlDict -entry deltaT -set 0.0001 \\\n        > logSimulation\n    foamDictionary system/controlDict -entry writeInterval -set 0.1 \\\n        >> logSimulation\n    foamDictionary system/controlDict -entry endTime -set 10 \\\n        >> logSimulation\n\n    echo "   - Copy 0.orig to 0"\n    cp -r 0.orig 0\n\n    echo "   - Renumber the mesh for speedup"\n    renumberMesh -overwrite >> logSimulation\n\n    echo "   - Start simulation"\n    foamRun >> logSimulation\nfi\n\n\n#------------------------------------------------------------------------------\necho "   - Move the mesh using the solver: moveDynamicMesh"\nif [ $input -eq 2 ]\nthen\n    echo "   - Change timestep and save interval"\n    foamDictionary system/controlDict -entry deltaT -set 0.1 \\\n        > logSimulation\n    foamDictionary system/controlDict -entry writeInterval -set 0.1 \\\n        >> logSimulation\n    foamDictionary system/controlDict -entry endTime -set 2 \\\n        >> logSimulation\n\n    echo "   - Start moving the mesh (moveDynamicMesh)"\n    moveDynamicMesh >> logSimulation\nfi\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\n-------------------------------------------------------------------------------\nEnd of moving\\n\\n\n"\n\n\n#------------------------------------------------------------------------------\n',
    'system/controlDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version         2;\n    format          ascii;\n    class           dictionary;\n    location        "system";\n    object          controlDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\napplication     foamRun;\n\nsolver          incompressibleFluid;\n\nstartFrom       startTime;\n\nstartTime       0;\n\nstopAt          endTime;\n\nendTime         10;\n\ndeltaT          0.2;\n\nwriteControl    adjustableRunTime;\n\nwriteInterval   0.2;\n\npurgeWrite      0;\n\nwriteFormat     binary;\n\nwritePrecision  6;\n\nwriteCompression off;\n\ntimeFormat      general;\n\ntimePrecision   6;\n\nrunTimeModifiable true;\n\nadjustTimeStep  yes;\n\nmaxCo           2;\n\n\n// ************************************************************************* //\n',
    'system/createPatchDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      createPatchDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Do a synchronisation of coupled points after creation of any patches.\n// Note: this does not work with points that are on multiple coupled patches\n//       with transformations (i.e. cyclics).\npointSync false;\n\n// Patches to create.\npatches\n(\n    {\n        //- Master side patch\n        name                AMI1;\n        patchInfo\n        {\n            type            patch;\n        }\n\n        constructFrom patches;\n        patches (AMI);\n    }\n\n    {\n        //- Slave side patch\n        name                AMI2;\n        patchInfo\n        {\n            type            patch;\n        }\n\n        constructFrom patches;\n        patches (AMI_slave);\n    }\n);\n\n// ************************************************************************* //\n',
    'system/fvSchemes': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      fvSchemes;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nddtSchemes\n{\n    default         Euler;\n}\n\ngradSchemes\n{\n    default         Gauss linear;\n    grad(p)         Gauss linear;\n    grad(U)         cellLimited Gauss linear 1;\n}\n\ndivSchemes\n{\n    default         none;\n//    div(phi,U)      Gauss upwind;\n    div(phi,U)      Gauss linearUpwind grad(U);\n    div((nuEff*dev2(T(grad(U))))) Gauss linear;\n}\n\nlaplacianSchemes\n{\n    default         Gauss linear limited corrected 0.33;\n}\n\ninterpolationSchemes\n{\n    default         linear;\n}\n\nsnGradSchemes\n{\n    default         limited corrected 0.33;\n}\n\n\n// ************************************************************************* //\n',
    'system/fvSolution': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      fvSolution;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsolvers\n{\n    pcorr\n    {\n        solver          GAMG;\n        tolerance       1e-2;\n        relTol          0;\n        smoother        DICGaussSeidel;\n        cacheAgglomeration no;\n        maxIter         50;\n    }\n    pcorrFinal\n    {\n        $pcorr;\n    }\n\n    p\n    {\n        $pcorr;\n        tolerance       1e-5;\n        relTol          0.01;\n    }\n\n    pFinal\n    {\n        $p;\n        tolerance       1e-6;\n        relTol          0;\n    }\n\n    U \n    {\n        solver          smoothSolver;\n        smoother        symGaussSeidel;\n        tolerance       1e-6;\n        relTol          0.1;\n    }\n\n    UFinal\n    {\n        solver          smoothSolver;\n        smoother        symGaussSeidel;\n        tolerance       1e-6;\n        relTol          0;\n    }\n\n    MeshPhi\n    {\n        solver          smoothSolver;\n        smoother        symGaussSeidel;\n        tolerance       1e-1;\n        relTol          0;\n    }\n}\n\nPIMPLE\n{\n    //- Correct the fluxes based on mesh motion. See header files of the solver\n    correctPhi          true;\n\n    //- Correct the fluxes based on mesh motion. See header files of the solver\n    correctMeshPhi      true;\n\n    //- Turn on of off the momentum predictor. In a numerical point of view\n    //  not necessary. Useful for 2-phase and high viscosity ratios\n    momentumPredictor   false;\n\n    //- Calculate the turbulence in each outer loop or only at the end of one\n    //  time step calculation. High turbulent flow calculation should calculate\n    //  the turbulence properties in each outer loop\n    turbOnFinalIterOnly false;\n\n    //- Use the SIMPLE(C) := C =  consistent / corrected algorithm for\n    //  the outer corrections. A pressure term that is neglected in the\n    //  SIMPLE algorithm is included. More inner calculations but the\n    //  coupling U-p in general is solved faster\n    consistent          true;\n\n    //- Mesh non-orthogonality correctors. Foam handles non-orthogonality quite\n    //  good, so there is no need to use or only up to 2 - 3\n    nNonOrthogonalCorrectors 0;\n\n    //- Outer loops, re-calculation around p-U and other equations within\n    //  one time step. For stiff problems while using under-relaxation\n    nOuterCorrectors    15;\n\n    //- Pressure corrections\n    nCorrectors         2;\n\n    //- If the transient solution tends towards a steady state solution,\n    //  end the calculation after the residual control is reached\n    residualControl\n    {\n        p   1e-5;\n        U   4e-6;\n    }\n\n    //- Control over each time step. The outer loops are recalculated\n    //  till the residuals are reached. For outer loops, we can use\n    //  under-relaxation as it is kind of a SIMPLE loop. Stiff problems\n    //  can be handled and the time step can be increased. Further information\n    //  are given in the book Mathematics, Numerics, Derivations and OpenFOAM\n    outerCorrectorResidualControl\n    {\n        //- Weak control - bad accuracy but faster\n        p\n        {\n            relTol      0;\n            tolerance   1e-3;\n        }\n\n        U\n        {\n            relTol      0;\n            tolerance   1e-3;\n        }\n    }\n}\n\n//- Relaxation factors applied to the fields or equations in the outer loops\n//  If nOuterCorrectors is not used, no underrelaxation should be placed.\n//  Always use the *.Final factor too, only you really know what your are doing\n//  ++ Relaxation of the final outer correction is possible, if the residual\n//     controls are very strict.\nrelaxationFactors\n{\n    //- Relaxation of the fields: See doxygen\n    //  Range [0-1] while 0 does not change the field (no sense)\n    fields\n    {\n        p               0.85;\n        pFinal          1;\n    }\n    //- Relaxation of the equation:\n    //  Factor: -1 disables the usage\n    //  Factor: 1 makes the matrix diagonal dominant or at least equal\n    //          --> matrix might be manipulated\n    //  Factor: 0 < alpha < 1; underrelaxation - make matrix diagonal dominat\n    //  Factor: alpha > 1; over-relaxation - make matrix diagonal dominat weak\n    //          --> can be used in some cases, generally not stable\n    equations\n    {\n        "(k|S|omega|U)"           0.8;\n        "(k|S|omega|U)Final"      1;\n    }\n}\n\n\n// ************************************************************************* //\n',
    'system/meshQualityDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      meshQualityDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Include defaults parameters from master dictionary\n#includeEtc "caseDicts/mesh/generation/meshQualityDict"\n\n\n// ************************************************************************* //\n',
    'system/snappyHexMeshDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      snappyHexMeshDict;\n}\n\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\n// Which of the steps to run\ncastellatedMesh true;\nsnap            true;\naddLayers       false;\n\n\n// Geometry. Definition of all surfaces. All surfaces are of class\n// searchableSurface.\n// Surfaces are used\n// - to specify refinement for any mesh cell intersecting it\n// - to specify refinement for any mesh cell inside/outside/near\n// - to \'snap\' the mesh boundary to the surface\ngeometry\n{\n    regionSTL\n    {\n        file "regionSTL.stl";\n        type triSurfaceMesh;\n        regions\n        {\n            inlet1          { name inlet1; }\n            inlet2          { name inlet2; }\n            outlet          { name outlet; }\n            movingWall      { name movingWalls; }\n            staticWall      { name staticWalls; }\n        }\n    }\n\n    AMI\n    {\n        file "AMI.stl";\n        type triSurfaceMesh;\n    }\n};\n\n\n\n// Settings for the castellatedMesh generation.\ncastellatedMeshControls\n{\n\n    // Refinement parameters\n    // ~~~~~~~~~~~~~~~~~~~~~\n\n    // If local number of cells is >= maxLocalCells on any processor\n    // switches from from refinement followed by balancing\n    // (current method) to (weighted) balancing before refinement.\n    maxLocalCells 2000000;\n\n    // Overall cell limit (approximately). Refinement will stop immediately\n    // upon reaching this number so a refinement level might not complete.\n    // Note that this is the number of cells before removing the part which\n    // is not \'visible\' from the keepPoint. The final number of cells might\n    // actually be a lot less.\n    maxGlobalCells 4000000;\n\n    // The surface refinement loop might spend lots of iterations refining just a\n    // few cells. This setting will cause refinement to stop if <= minimumRefine\n    // are selected for refinement. Note: it will at least do one iteration\n    // (unless the number of cells to refine is 0)\n    minRefinementCells 0;\n\n    // Number of buffer layers between different levels.\n    // 1 means normal 2:1 refinement restriction, larger means slower\n    // refinement.\n    nCellsBetweenLevels 3;\n\n\n\n    // Explicit feature edge refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies a level for any cell intersected by its edges.\n    // This is a featureEdgeMesh, read from constant/triSurface for now.\n    features\n    (\n    );\n\n\n\n    // Surface based refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies two levels for every surface. The first is the minimum level,\n    // every cell intersecting a surface gets refined up to the minimum level.\n    // The second level is the maximum level. Cells that \'see\' multiple\n    // intersections where the intersections make an\n    // angle > resolveFeatureAngle get refined up to the maximum level.\n\n    refinementSurfaces\n    {\n        regionSTL\n        {\n            // Surface-wise min and max refinement level\n            level (0 0);\n            regions\n            {\n                inlet1          { level (1 1); patchInfo { type patch; }}\n                inlet2          { level (1 1); patchInfo { type patch; }}\n                outlet          { level (1 1); patchInfo { type patch; }}\n                movingWall      { level (2 2); patchInfo { type wall; }}\n                staticWall      { level (2 2); patchInfo { type wall; }}\n            }\n        }\n\n        AMI\n        {\n            level (2 2);\n            \n            faceType boundary;\n            cellZone innerAMI;\n            faceZone innerAMI;\n            cellZoneInside inside;\n        }\n    }\n\n    resolveFeatureAngle 30;\n\n\n    // Region-wise refinement\n    // ~~~~~~~~~~~~~~~~~~~~~~\n\n    // Specifies refinement level for cells in relation to a surface. One of\n    // three modes\n    // - distance. \'levels\' specifies per distance to the surface the\n    //   wanted refinement level. The distances need to be specified in\n    //   descending order.\n    // - inside. \'levels\' is only one entry and only the level is used. All\n    //   cells inside the surface get refined up to the level. The surface\n    //   needs to be closed for this to be possible.\n    // - outside. Same but cells outside.\n\n    refinementRegions\n    {\n    }\n\n\n    // Mesh selection\n    // ~~~~~~~~~~~~~~\n\n    // After refinement patches get added for all refinementSurfaces and\n    // all cells intersecting the surfaces get put into these patches. The\n    // section reachable from the locationInMesh is kept.\n    // NOTE: This point should never be on a face, always inside a cell, even\n    // after refinement.\n    // This is an outside point locationInMesh (-0.033 -0.033 0.0033);\n    locationInMesh (0.095 0 0.01); // Inside point\n\n    // Whether any faceZones (as specified in the refinementSurfaces)\n    // are only on the boundary of corresponding cellZones or also allow\n    // free-standing zone faces. Not used if there are no faceZones.\n    allowFreeStandingZoneFaces false;\n}\n\n\n\n// Settings for the snapping.\nsnapControls\n{\n    //- Number of patch smoothing iterations before finding correspondence\n    //  to surface\n    nSmoothPatch 3;\n\n    //- Relative distance for points to be attracted by surface feature point\n    //  or edge. True distance is this factor times local\n    //  maximum edge length.\n    tolerance 1.0;\n\n    //- Number of mesh displacement relaxation iterations.\n    nSolveIter 100;\n\n    //- Maximum number of snapping relaxation iterations. Should stop\n    //  before upon reaching a correct mesh.\n    nRelaxIter 5;\n\n    // Feature snapping\n\n        //- Number of feature edge snapping iterations.\n        //  Leave out altogether to disable.\n        nFeatureSnapIter 5;\n\n        //- Detect (geometric) features by sampling the surface\n        implicitFeatureSnap true;\n\n        //- Use castellatedMeshControls::features\n        explicitFeatureSnap false;\n\n        //- Detect features between multiple surfaces\n        //  (only for explicitFeatureSnap, default = false)\n        multiRegionFeatureSnap false;\n}\n\n\n\n// Settings for the layer addition.\naddLayersControls\n{\n    // Are the thickness parameters below relative to the undistorted\n    // size of the refined cell outside layer (true) or absolute sizes (false).\n    relativeSizes true;\n\n    // Per final patch (so not geometry!) the layer information\n    layers\n    {\n    }\n\n    // Expansion factor for layer mesh\n    expansionRatio 1.0;\n\n\n    // Wanted thickness of final added cell layer. If multiple layers\n    // is the thickness of the layer furthest away from the wall.\n    // See relativeSizes parameter.\n    finalLayerThickness 0.3;\n\n    // Minimum thickness of cell layer. If for any reason layer\n    // cannot be above minThickness do not add layer.\n    // See relativeSizes parameter.\n    minThickness 0.25;\n\n    // If points get not extruded do nGrow layers of connected faces that are\n    // also not grown. This helps convergence of the layer addition process\n    // close to features.\n    nGrow 0;\n\n\n    // Advanced settings\n\n    // When not to extrude surface. 0 is flat surface, 90 is when two faces\n    // are perpendicular\n    featureAngle 30;\n\n    // Maximum number of snapping relaxation iterations. Should stop\n    // before upon reaching a correct mesh.\n    nRelaxIter 5;\n\n    // Number of smoothing iterations of surface normals\n    nSmoothSurfaceNormals 1;\n\n    // Number of smoothing iterations of interior mesh movement direction\n    nSmoothNormals 3;\n\n    // Smooth layer thickness over surface patches\n    nSmoothThickness 10;\n\n    // Stop layer growth on highly warped cells\n    maxFaceThicknessRatio 0.5;\n\n    // Reduce layer growth where ratio thickness to medial\n    // distance is large\n    maxThicknessToMedialRatio 0.3;\n\n    // Angle used to pick up medial axis points\n    minMedianAxisAngle 90;\n\n    // Create buffer region for new layer terminations\n    nBufferCellsNoExtrude 0;\n\n\n    // Overall max number of layer addition iterations. The mesher will exit\n    // if it reaches this number of iterations; possibly with an illegal\n    // mesh.\n    nLayerIter 50;\n\n    // Max number of iterations after which relaxed meshQuality controls\n    // get used. Up to nRelaxIter it uses the settings in meshQualityControls,\n    // after nRelaxIter it uses the values in meshQualityControls::relaxed.\n    nRelaxedIter 20;\n}\n\n\n\n// Generic mesh quality settings. At any undoable phase these determine\n// where to undo.\nmeshQualityControls\n{\n    #include "meshQualityDict"\n\n    // Optional : some meshing phases allow usage of relaxed rules.\n    // See e.g. addLayersControls::nRelaxedIter.\n    relaxed\n    {\n        //- Maximum non-orthogonality allowed. Set to 180 to disable.\n        maxNonOrtho 75;\n    }\n\n    // Advanced\n\n    //- Number of error distribution iterations\n    nSmoothScale 4;\n    //- amount to scale back displacement at error points\n    errorReduction 0.75;\n}\n\n\n// Advanced\n\n// Write flags\nwriteFlags\n(\n    scalarLevels    // write volScalarField with cellLevel for postprocessing\n    layerSets       // write cellSets, faceSets of faces in layer\n    layerFields     // write volScalarField for layer coverage\n);\n\n\n// Merge tolerance. Is fraction of overall bounding box of initial mesh.\n// Note: the write tolerance needs to be higher than this.\nmergeTolerance 1E-6;\n\n\n// ************************************************************************* //\n',
}
